count = signal(0);
double = computed(() => this.count() * 2);
inc() { this.count.update(c => c + 1); }
// szablon: {{ count() }} / {{ double() }}

todos = signal<Todo[]>([]);
add(t: Todo) { this.todos.update(list => [...list, t]); }
toggle(id: number) {
  this.todos.update(l => l.map(t => t.id === id ? { ...t, done: !t.done } : t));
}

filter = signal<'all' | 'done'>('all');
visible = computed(() =>
  this.filter() === 'all' ? this.todos() : this.todos().filter(t => t.done)
);

constructor() {
  effect(onCleanup => {
    const theme = this.theme();
    localStorage.setItem('theme', theme);
    const t = setTimeout(() => this.analytics.track('theme', theme), 500);
    onCleanup(() => clearTimeout(t));
  });
}

effect(() => {
  const id = this.userId();                       // zależność
  const cfg = untracked(() => this.settings());   // bez zależności
  untracked(() => this.logger.log(id, cfg));      // zewnętrzny kod
});

const user = signal<User>(initial, {
  equal: (a, b) => a.id === b.id && a.version === b.version,
});

selected = linkedSignal<Item[], Item | undefined>({
  source: this.items,
  computation: (items, prev) =>
    items.find(i => i.id === prev?.value?.id) ?? items[0],
});

user = resource({
  params: () => ({ id: this.userId() }),
  loader: ({ params, abortSignal }) =>
    fetch(`/api/users/${params.id}`, { signal: abortSignal }).then(r => r.json()),
});

orders = rxResource({
  params: () => ({ page: this.page() }),
  stream: ({ params }) => this.api.getOrders(params.page),
});

user = httpResource<User>(() =>
  this.id() ? `/api/users/${this.id()}` : undefined
);
