user = input.required<User>();
disabled = input(false, { transform: booleanAttribute });
fullName = computed(() => `${this.user().first} ${this.user().last}`);

saved = output<Order>();
save() { this.saved.emit(this.form.getRawValue()); }
// <app-order-form (saved)="onSaved($event)" />

// dziecko
checked = model(false);
toggle() { this.checked.update(v => !v); }
// rodzic: <app-toggle [(checked)]="isOn" />  // isOn = signal(true)

input = viewChild.required<ElementRef<HTMLInputElement>>('search');
constructor() {
  afterNextRender(() => this.input().nativeElement.focus());
}

private route = inject(ActivatedRoute);
id = toSignal(this.route.paramMap.pipe(map(p => p.get('id'))), {
  initialValue: null,
});

results = toSignal(
  toObservable(this.query).pipe(
    debounceTime(300),
    switchMap(q => this.api.search(q)),
  ),
  { initialValue: [] },
);

@Injectable({ providedIn: 'root' })
export class CartStore {
  private readonly _items = signal<CartItem[]>([]);
  readonly items = this._items.asReadonly();
  readonly total = computed(() => this._items().reduce((s, i) => s + i.price * i.qty, 0));
  add(item: CartItem) { this._items.update(l => [...l, item]); }
}

export const TodoStore = signalStore(
  { providedIn: 'root' },
  withState({ todos: [] as Todo[], filter: 'all' as Filter }),
  withComputed(({ todos }) => ({ left: computed(() => todos().filter(t => !t.done).length) })),
  withMethods(store => ({
    setFilter(filter: Filter) { patchState(store, { filter }); },
  })),
);

